    staleTime: 5 * 60 * 1000,
  });

  const {
    data: applications,
    isLoading,
    error,
  } = useQuery<Application[]>({
    queryKey: ["applications", jobId],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("applications")
        .select(
          "id, job_id, name, email, phone, linkedin_url, resume_path, resume_filename, status, created_at, custom_fields, auto_disqualified, disqualify_reason"
        )
        .eq("job_id", jobId)
        .order("created_at", { ascending: false });
      if (error) throw new Error(error.message);
      return (data ?? []) as Application[];
    },
    enabled: !!jobId,
    staleTime: 30_000,
  });

  // Realtime subscription — auto-refresh when new applications arrive
  useEffect(() => {
    const channel = supabase
      .channel(`applications-${jobId}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "applications",
          filter: `job_id=eq.${jobId}`,
        },
        () => {
          queryClient.invalidateQueries({ queryKey: ["applications", jobId] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [jobId, queryClient]);

  const updateStatus = useMutation({
    mutationFn: async ({
      applicationId,
      newStatus,
    }: {
      applicationId: string;
      newStatus: ApplicationStatus;
    }) => {
      const { error } = await supabase
        .from("applications")
        .update({ status: newStatus })
        .eq("id", applicationId);
      if (error) throw new Error(error.message);
    },
    onMutate: ({ applicationId }) => setUpdatingId(applicationId),
    onSuccess: (_, { applicationId, newStatus }) => {
      queryClient.setQueryData<Application[]>(
        ["applications", jobId],
        (prev) =>
          (prev ?? []).map((a) =>
            a.id === applicationId ? { ...a, status: newStatus } : a
          )
      );
      toast.success(`Application marked as ${STATUS_LABELS[newStatus]}`);
    },
    onError: (err: Error) => toast.error(err.message || "Failed to update status"),
    onSettled: () => setUpdatingId(null),
  });

  const downloadResume = async (resumePath: string, filename: string) => {
    const { data, error } = await supabase.storage
      .from("resumes")
      .download(resumePath);
    if (error || !data) {
      toast.error("Failed to download resume");
      return;
    }
    const url = URL.createObjectURL(data);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
  };

  const formatDate = (iso: string) =>
    new Date(iso).toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric",
    });

  if (isLoading) {
    return (
      <div className="space-y-3">
        {[0, 1, 2, 3].map((i) => (
          <Skeleton key={i} className="h-12 w-full rounded-md" />
        ))}
      </div>
    );
  }

  if (error) {
    return (
      <div className="rounded-lg border border-destructive/30 bg-destructive/5 p-4 text-sm text-destructive">
        Failed to load applications. Please refresh the page.
      </div>
    );
  }

  if (!applications || applications.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 space-y-4">
        <div className="rounded-xl bg-muted/50 p-4">
          <Users className="h-8 w-8 text-muted-foreground/50" />
        </div>
        <div className="text-center space-y-1">
          <h3 className="text-sm font-medium">No applications yet</h3>
          <p className="text-sm text-muted-foreground max-w-xs">
            Share your apply link to start receiving applications from candidates.
          </p>
        </div>
      </div>
    );
  }

  const visibleApplications = hideDisqualified
    ? (applications ?? []).filter((a) => !a.auto_disqualified)
    : (applications ?? []);

  const disqualifiedCount = (applications ?? []).filter((a) => a.auto_disqualified).length;

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <p className="text-sm text-muted-foreground">
          {applications.length} application{applications.length !== 1 ? "s" : ""}
          {disqualifiedCount > 0 && (
            <span className="ml-1.5 text-xs text-red-600 dark:text-red-400">
              ({disqualifiedCount} auto-disqualified)
            </span>
          )}
        </p>
        <div className="flex items-center gap-3 flex-wrap">
          {disqualifiedCount > 0 && (
            <div className="flex items-center gap-1.5">
              <Switch
                id="hide-disqualified"
                checked={hideDisqualified}
                onCheckedChange={setHideDisqualified}
                className="scale-75"
              />
              <Label htmlFor="hide-disqualified" className="text-xs cursor-pointer text-muted-foreground">
                Hide disqualified
              </Label>
            </div>
          )}
          <div className="flex items-center gap-2 text-xs text-muted-foreground">
            {(["pending", "reviewed", "shortlisted", "rejected"] as const).map((s) => {
              const count = applications.filter((a) => a.status === s).length;
              if (count === 0) return null;
              return (
                <span
                  key={s}
                  className={`px-2 py-0.5 rounded-full text-[11px] font-medium ${STATUS_COLORS[s]}`}
                >
                  {count} {STATUS_LABELS[s]}
                </span>
              );
            })}
          </div>
        </div>
      </div>

      <div className="rounded-md border border-border overflow-hidden">
        <div className="overflow-x-auto">
          <Table>
            <TableHeader className="bg-muted/40">
              <TableRow>
                <TableHead className="pl-4">Candidate</TableHead>
                <TableHead>Contact</TableHead>
                <TableHead>Resume</TableHead>
                <TableHead className="w-36">Status</TableHead>
                <TableHead className="w-28 text-right pr-4">Submitted</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {visibleApplications.map((app) => {
                const hasCustomFields =
                  app.custom_fields &&
                  Object.keys(app.custom_fields).length > 0;
                const isExpanded = expandedCustomFields.has(app.id);

                return (
                  <React.Fragment key={app.id}>
                    <TableRow
                      className={`align-middle ${app.auto_disqualified ? "opacity-60" : ""}`}
                    >
                      {/* Name + LinkedIn + disqualified badge */}
                      <TableCell className="pl-4 py-3">
                        <div className="space-y-0.5">
                          <div className="flex items-center gap-1.5 flex-wrap">
                            <p className="text-sm font-medium leading-tight">
                              {app.name}
                            </p>
                            {app.auto_disqualified && (
                              <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400">
                                <Ban className="h-2.5 w-2.5" />
                                Disqualified
                              </span>
                            )}
                          </div>
                          {app.auto_disqualified && app.disqualify_reason && (
                            <p className="text-[11px] text-red-600 dark:text-red-400">
                              {app.disqualify_reason}
                            </p>
                          )}
                          {app.linkedin_url && (
                            <a
                              href={app.linkedin_url}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="inline-flex items-center gap-1 text-xs text-primary hover:text-primary/80 transition-colors"
                            >
                              <ExternalLink className="h-3 w-3" />
                              LinkedIn
                            </a>
                          )}
                        </div>
                      </TableCell>

                      {/* Email + Phone */}
                      <TableCell className="py-3">
                        <div className="space-y-0.5">
                          <p className="text-xs text-muted-foreground truncate max-w-[180px]">
                            {app.email}
                          </p>
                          {app.phone && (
                            <p className="text-xs text-muted-foreground">
                              {app.phone}
                            </p>
                          )}
                        </div>
                      </TableCell>

                      {/* Resume download */}
                      <TableCell className="py-3">
                        {app.resume_path && app.resume_filename ? (
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-7 gap-1.5 text-xs px-2"
                            onClick={() =>
                              downloadResume(app.resume_path!, app.resume_filename!)
                            }
                            title={`Download ${app.resume_filename}`}
                          >
                            <Download className="h-3.5 w-3.5" />
                            {app.resume_filename.length > 20
                              ? app.resume_filename.slice(0, 18) + "…"
                              : app.resume_filename}
                          </Button>
                        ) : (
                          <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
                            <FileText className="h-3.5 w-3.5" />
                            No file
                          </span>
                        )}
                      </TableCell>

                      {/* Status select */}
                      <TableCell className="py-3">
                        <div className="relative">
                          {updatingId === app.id && (
                            <Loader2 className="absolute -left-5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 animate-spin text-primary" />
                          )}
                          <Select
                            value={app.status}
                            onValueChange={(val) =>
                              updateStatus.mutate({
                                applicationId: app.id,
                                newStatus: val as ApplicationStatus,
                              })
                            }
                            disabled={updatingId === app.id}
                          >
                            <SelectTrigger className="h-7 text-xs w-32">
                              <SelectValue>
                                <span
                                  className={`px-1.5 py-0.5 rounded text-[11px] font-medium ${STATUS_COLORS[app.status]}`}
                                >
                                  {STATUS_LABELS[app.status]}
                                </span>
                              </SelectValue>
                            </SelectTrigger>
                            <SelectContent>
                              {(
                                ["pending", "reviewed", "shortlisted", "rejected"] as const
                              ).map((s) => (
                                <SelectItem key={s} value={s} className="text-xs">
                                  <span
                                    className={`px-1.5 py-0.5 rounded text-[11px] font-medium ${STATUS_COLORS[s]}`}
                                  >
                                    {STATUS_LABELS[s]}
                                  </span>
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </div>
                      </TableCell>

                      {/* Date + expand custom fields */}
                      <TableCell className="text-right text-xs text-muted-foreground pr-4 py-3">
                        <div className="flex items-center justify-end gap-1.5">
                          {hasCustomFields && (
                            <button
                              onClick={() =>
                                setExpandedCustomFields((prev) => {
                                  const next = new Set(prev);
                                  if (next.has(app.id)) next.delete(app.id);
                                  else next.add(app.id);
                                  return next;
                                })
                              }
                              className="text-muted-foreground hover:text-foreground transition-colors"
                              title="Toggle custom answers"
                            >
                              {isExpanded ? (
                                <ChevronDown className="h-3.5 w-3.5" />
                              ) : (
                                <ChevronRight className="h-3.5 w-3.5" />
                              )}
                            </button>
                          )}
                          {formatDate(app.created_at)}
                        </div>
                      </TableCell>
                    </TableRow>

                    {/* Expanded custom fields row */}
                    {isExpanded && hasCustomFields && (
                      <TableRow key={`${app.id}-custom`} className="bg-muted/30">
                        <TableCell colSpan={5} className="pl-8 pr-4 py-3">
                          <div className="space-y-1.5">
                            <p className="text-[11px] font-medium text-muted-foreground uppercase tracking-wider mb-2">
                              Custom Answers
                            </p>
                            {Object.entries(app.custom_fields ?? {}).map(
                              ([fieldId, val]) => (
                                <div key={fieldId} className="flex gap-2 text-xs">
                                  <span className="text-muted-foreground shrink-0 min-w-[120px] truncate">
                                    {fieldId}:
                                  </span>
                                  <span className="text-foreground break-words">
                                    {Array.isArray(val)
                                      ? val.join(", ")
                                      : typeof val === "boolean"
                                      ? val
                                        ? "Yes"
                                        : "No"
                                      : String(val ?? "")}
                                  </span>
                                </div>
                              )
                            )}
                          </div>
                        </TableCell>
                      </TableRow>
                    )}
                  </React.Fragment>
                );
              })}
            </TableBody>
          </Table>
        </div>
      </div>
    </div>
  );
}

