const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const RESEND_API_KEY = Deno.env.get("RESEND_API_KEY");

// ── Simple in-memory rate limiter ──────────────────────────
// Limits: 5 submissions per IP per minute, 100 per job per hour
const ipBuckets = new Map<string, { count: number; resetAt: number }>();
const jobBuckets = new Map<string, { count: number; resetAt: number }>();

function isRateLimited(ip: string, jobId: string): string | null {
  const now = Date.now();

  // Per-IP: 5 per minute
  const ipEntry = ipBuckets.get(ip);
  if (ipEntry && now < ipEntry.resetAt) {
    if (ipEntry.count >= 5) return "Too many submissions. Please try again later.";
    ipEntry.count++;
  } else {
    ipBuckets.set(ip, { count: 1, resetAt: now + 60_000 });
  }

  // Per-job: 100 per hour
  const jobEntry = jobBuckets.get(jobId);
  if (jobEntry && now < jobEntry.resetAt) {
    if (jobEntry.count >= 100) return "This position has received too many applications right now. Please try again later.";
    jobEntry.count++;
  } else {
    jobBuckets.set(jobId, { count: 1, resetAt: now + 3_600_000 });
  }

  // Cleanup stale entries every 1000 checks
  if (ipBuckets.size > 1000) {
    for (const [k, v] of ipBuckets) { if (now >= v.resetAt) ipBuckets.delete(k); }
  }
  if (jobBuckets.size > 1000) {
    for (const [k, v] of jobBuckets) { if (now >= v.resetAt) jobBuckets.delete(k); }
  }

  return null;
}

