  title: string;
  description: string;
}

interface SocialLinks {
  website?: string;
  linkedin?: string;
  twitter?: string;
  instagram?: string;
  facebook?: string;
}

interface CareerPageConfig {
  id: string;
  team_id: string;
  company_name: string | null;
  slug: string | null;
  logo_url: string | null;
  brand_color: string | null;
  tagline: string | null;
  about: string | null;
