            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-semibold flex items-center gap-2">
                <Globe className="h-4 w-4 text-primary" />
                Published Jobs
              </CardTitle>
              <CardDescription className="text-xs">
                Toggle which jobs appear on your career page. Featured jobs appear first.
              </CardDescription>
            </CardHeader>
            <CardContent className="p-0">
              {jobsLoading ? (
                <JobsSkeleton />
              ) : jobs.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-14 space-y-3 text-center px-4">
                  <div className="rounded-xl bg-muted/50 p-4">
                    <Globe className="h-7 w-7 text-muted-foreground/40" />
                  </div>
                  <div className="space-y-1">
                    <p className="text-sm font-medium text-foreground">No jobs yet</p>
                    <p className="text-sm text-muted-foreground max-w-xs">
                      Create a job posting from the dashboard to list it on your career page.
                    </p>
                  </div>
                </div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="text-xs">Title</TableHead>
                      <TableHead className="text-xs hidden sm:table-cell">Location</TableHead>
                      <TableHead className="text-xs hidden md:table-cell">Expires</TableHead>
                      <TableHead className="text-xs hidden lg:table-cell">Analytics</TableHead>
                      <TableHead className="text-xs text-right pr-4">Published</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {jobs.map((job) => {
                      const isToggling = togglingJobId === job.id;
                      const published = job.is_published ?? false;
                      const isExpired = job.expires_at
                        ? new Date(job.expires_at) < new Date()
                        : false;
                      return (
                        <TableRow key={job.id}>
                          <TableCell className="text-sm font-medium max-w-[200px]">
                            <div className="flex items-center gap-1.5">
                              <span className="truncate" title={job.title ?? ""}>
                                {job.title || <span className="text-muted-foreground italic">Untitled</span>}
                              </span>
                              {job.is_featured && (
                                <Badge variant="secondary" className="text-[10px] px-1 py-0 gap-0.5 shrink-0">
                                  <Star className="h-2.5 w-2.5" />
                                  Featured
                                </Badge>
                              )}
                            </div>
                            {job.employment_type && (
                              <span className="text-xs text-muted-foreground">{job.employment_type}</span>
                            )}
                          </TableCell>
                          <TableCell className="text-sm text-muted-foreground hidden sm:table-cell">
                            {job.location || "—"}
                          </TableCell>
                          <TableCell className="hidden md:table-cell">
                            {job.expires_at ? (
                              <span className={`text-xs ${isExpired ? "text-destructive" : "text-muted-foreground"}`}>
                                {isExpired ? "Expired" : new Date(job.expires_at).toLocaleDateString()}
                              </span>
                            ) : (
                              <span className="text-xs text-muted-foreground">—</span>
                            )}
                          </TableCell>
                          <TableCell className="hidden lg:table-cell">
                            <span className="text-xs text-muted-foreground whitespace-nowrap">
                              {(job.view_count ?? 0).toLocaleString()} views
                              {" · "}
                              {(job.apply_count ?? 0).toLocaleString()} applied
                            </span>
                          </TableCell>
                          <TableCell className="text-right pr-4">
                            {isToggling ? (
                              <div className="flex justify-end">
                                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                              </div>
                            ) : (
                              <Switch
                                checked={published}
                                onCheckedChange={() =>
                                  toggleJobPublished.mutate({ jobId: job.id, current: published })
                                }
                                disabled={isToggling}
                                aria-label={`${published ? "Unpublish" : "Publish"} ${job.title ?? "job"}`}
                              />
                            )}
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </div>
      </main>
    </SidebarLayout>
  );
};

export default CareerSettings;

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import SidebarLayout from "@/components/SidebarLayout";
import AppHeader from "@/components/AppHeader";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Megaphone } from "lucide-react";
import { format } from "date-fns";

interface ChangelogEntry {
  id: string;
  version: string;
  title: string;
  description: string;
  category: string;
  published_at: string;
}

const categoryVariant: Record<string, "default" | "secondary" | "outline"> = {
  feature: "default",
  improvement: "secondary",
  bugfix: "outline",
};

const categoryLabel: Record<string, string> = {
  feature: "Feature",
  improvement: "Improvement",
  bugfix: "Bug Fix",
};

const ChangelogContent = () => {
  const { data: entries, isLoading } = useQuery({
    queryKey: ["changelog_public"],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("changelog")
        .select("id, version, title, description, category, published_at")
        .eq("status", "published")
        .order("published_at", { ascending: false });
      if (error) throw error;
      return data as ChangelogEntry[];
    },
  });

  return (
    <main className="w-full max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
      <div className="flex items-center gap-3">
        <Megaphone className="h-5 w-5 text-primary" />
        <h1 className="text-2xl font-bold text-foreground">Changelog</h1>
      </div>
      <p className="text-sm text-muted-foreground">New features, improvements, and fixes.</p>

      {isLoading ? (
        <div className="space-y-4">
          {[0, 1, 2].map((i) => (
            <Card key={i} className="border border-border/60 shadow-sm">
              <CardContent className="p-5 space-y-3">
                <div className="flex gap-2">
                  <Skeleton className="h-5 w-16 rounded-full" />
                  <Skeleton className="h-5 w-20 rounded-full" />
                </div>
                <Skeleton className="h-5 w-3/4" />
                <Skeleton className="h-4 w-full" />
                <Skeleton className="h-4 w-2/3" />
              </CardContent>
            </Card>
          ))}
        </div>
      ) : !entries || entries.length === 0 ? (
        <Card className="border border-border/60 shadow-sm">
          <CardContent className="p-8 text-center">
            <p className="text-sm text-muted-foreground">No updates yet. Check back soon.</p>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-4">
          {entries.map((entry) => (
            <Card key={entry.id} className="border border-border/60 shadow-sm">
              <CardContent className="p-5 space-y-3">
                <div className="flex items-center gap-2 flex-wrap">
                  <Badge variant="outline" className="text-xs font-mono">{entry.version}</Badge>
                  <Badge variant={categoryVariant[entry.category] ?? "secondary"} className="text-xs">
                    {categoryLabel[entry.category] ?? entry.category}
                  </Badge>
                  <span className="text-xs text-muted-foreground ml-auto">
                    {format(new Date(entry.published_at), "MMM d, yyyy")}
                  </span>
                </div>
                <h2 className="text-base font-semibold text-foreground">{entry.title}</h2>
                <p className="text-sm text-muted-foreground leading-relaxed whitespace-pre-line">{entry.description}</p>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </main>
  );
};

const Changelog = () => {
  const { user } = useAuth();

  if (user) {
    return (
      <SidebarLayout>
        <ChangelogContent />
      </SidebarLayout>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      <AppHeader />
      <ChangelogContent />
    </div>
  );
};

export default Changelog;

