import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { LogOut, Zap, MessageCircle } from "lucide-react";
import { toast } from "sonner";
import AvailabilitySettings from "@/components/AvailabilitySettings";


const Settings = () => {
  const { user, profile, signOut, refreshProfile } = useAuth();
  const { team } = useTeam();
  const autoRank = profile?.auto_rank_enabled ?? true;
  const [whatsappNumber, setWhatsappNumber] = useState<string>((profile as any)?.whatsapp_number ?? "");
  const [savingWhatsapp, setSavingWhatsapp] = useState(false);

  const toggleAutoRank = async (enabled: boolean) => {
    if (!user) return;
    try {
      const { error } = await supabase
        .from("profiles")
        .update({ auto_rank_enabled: enabled } as any)
        .eq("user_id", user.id);
      if (error) throw error;
      await refreshProfile();
      toast.success(enabled ? "Auto-rank enabled" : "Auto-rank disabled");
    } catch {
      toast.error("Failed to update setting");
    }
  };

  const saveWhatsappNumber = async () => {
    if (!user) return;
    setSavingWhatsapp(true);
    try {
      const { error } = await supabase
        .from("profiles")
        .update({ whatsapp_number: whatsappNumber.trim() || null } as any)
        .eq("user_id", user.id);
      if (error) throw error;
      await refreshProfile();
      toast.success("WhatsApp number saved");
    } catch {
      toast.error("Failed to save WhatsApp number");
    } finally {
      setSavingWhatsapp(false);
    }
  };

  return (
    <SidebarLayout>
      <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
        <h1 className="text-2xl font-bold text-foreground mb-6">Settings</h1>
        <div className="space-y-6">
          {/* Auto-rank toggle */}
          <Card className="border border-border/60 shadow-sm">
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Zap className="h-5 w-5 text-primary" />
                  <CardTitle className="text-sm font-semibold">Auto-rank resumes</CardTitle>
                </div>
                <Switch checked={autoRank} onCheckedChange={toggleAutoRank} />
              </div>
              <CardDescription>
                {autoRank
                  ? "Resumes are automatically scored after upload. Credits are used immediately."
                  : "Resumes stay as Pending after upload. You choose when to rank and spend credits."}
              </CardDescription>
            </CardHeader>
          </Card>

          {/* WhatsApp number */}
          <Card className="border border-border/60 shadow-sm">
            <CardHeader className="pb-3">
              <div className="flex items-center gap-2">
                <MessageCircle className="h-5 w-5 text-[#25D366]" />
                <CardTitle className="text-sm font-semibold">WhatsApp Number</CardTitle>
              </div>
              <CardDescription>
                Your WhatsApp number is pre-filled when messaging candidates. Include country code (e.g. +1 555 123 4567).
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="flex items-center gap-2">
                <div className="flex-1">
                  <Label htmlFor="whatsapp-number" className="sr-only">WhatsApp Number</Label>
                  <Input
                    id="whatsapp-number"
                    value={whatsappNumber}
                    onChange={(e) => setWhatsappNumber(e.target.value)}
                    placeholder="+1 555 123 4567"
                    type="tel"
                  />
                </div>
                <Button
                  size="sm"
                  onClick={saveWhatsappNumber}
                  disabled={savingWhatsapp}
                  className="shrink-0"
                >
                  {savingWhatsapp ? "Saving..." : "Save"}
                </Button>
              </div>
            </CardContent>
          </Card>

          {user && (
            <AvailabilitySettings userId={user.id} teamId={team?.id} />
          )}


          <Card className="border border-border/60 shadow-sm">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-sm font-semibold">
                <LogOut className="h-5 w-5" />
                Account
              </CardTitle>
            </CardHeader>
            <CardContent>
              <Button variant="outline" onClick={signOut}>
                Sign out
              </Button>
            </CardContent>
          </Card>
        </div>
      </main>
    </SidebarLayout>
  );
};

export default Settings;

