122	  const split = sub + top + bonus;
123	  const totalCredits = split > 0 ? split : (profile?.credits ?? 0);
124	
125	  // ── load extended profile (React Query, independent of useAuth) ──────────
126	  const { data: fullProfile, isLoading: profileLoading } = useQuery<ExtendedProfile>({
127	    queryKey: ["profileFull", user?.id],
