432	              </div>
433	
434	              {/* ── Work Details ──────────────────────────────────────── */}
435	              <Separator className="my-6" />
436	              <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground mb-4">
437	                Work Details
438	              </p>
439	
440	              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
