453	                </div>
454	
455	                {/* Company */}
456	                <div className="space-y-1.5">
457	                  <Label htmlFor="company" className="text-sm">Company</Label>
458	                  <Input
459	                    id="company"
460	                    placeholder="Acme Corp"
461	                    value={form.company}
462	                    onChange={set("company")}
463	                  />
464	                </div>
465	
466	                {/* Location — full width */}
467	                <div className="space-y-1.5 sm:col-span-2">
468	                  <Label htmlFor="location" className="text-sm flex items-center gap-1.5">
469	                    <MapPin className="h-3.5 w-3.5 text-muted-foreground" />
470	                    Location
471	                  </Label>
472	                  <Input
