                {/* Hidden file input */}
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  className="hidden"
                  onChange={handleAvatarFile}
                />
              </div>

              {/* ── Personal Information ──────────────────────────────── */}
              <Separator className="my-6" />
              <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground mb-4">
                Personal Information
              </p>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {/* Full name */}
                <div className="space-y-1.5">
                  <Label htmlFor="full-name" className="text-sm">Full Name</Label>
                  <Input
                    id="full-name"
                    placeholder="Jane Smith"
                    value={form.full_name}
                    onChange={set("full_name")}
                  />
                </div>

                {/* Username */}
                <div className="space-y-1.5">
                  <Label htmlFor="username" className="text-sm">Username</Label>
                  <div className="flex rounded-md border border-input focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-0 overflow-hidden">
                    <span className="flex items-center px-3 text-sm text-muted-foreground bg-muted border-r border-input shrink-0 select-none">
                      @
                    </span>
                    <input
                      id="username"
                      className="flex-1 h-9 px-3 py-1 text-sm bg-background outline-none placeholder:text-muted-foreground"
                      placeholder="janesmith"
                      value={form.username}
                      onChange={(e) => setForm((f) => ({ ...f, username: e.target.value }))}
                    />
                  </div>
                </div>

                {/* Email — read-only */}
                <div className="space-y-1.5">
                  <Label htmlFor="email" className="text-sm">Email</Label>
                  <Input
                    id="email"
                    value={user?.email ?? ""}
                    disabled
                    className="cursor-not-allowed opacity-60"
                  />
                </div>

                {/* Member since — read-only display */}
                <div className="space-y-1.5">
                  <Label className="text-sm">Member Since</Label>
                  <div className="h-9 flex items-center px-3 rounded-md border border-input bg-muted/40 text-sm text-muted-foreground">
                    {memberSince}
                  </div>
                </div>

                {/* Bio — full width */}
                <div className="space-y-1.5 sm:col-span-2">
                  <Label htmlFor="bio" className="text-sm">Bio</Label>
                  <Textarea
                    id="bio"
                    placeholder="A short bio about yourself…"
                    value={form.bio}
                    onChange={set("bio")}
                    maxLength={160}
                    rows={3}
                    className="resize-none"
                  />
                  <p className="text-xs text-muted-foreground text-right tabular-nums">
                    {form.bio.length}/160
                  </p>
                </div>
              </div>

              {/* ── Work Details ──────────────────────────────────────── */}
              <Separator className="my-6" />
              <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground mb-4">
                Work Details
              </p>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {/* Job title */}
                <div className="space-y-1.5">
                  <Label htmlFor="job-title" className="text-sm flex items-center gap-1.5">
                    <Briefcase className="h-3.5 w-3.5 text-muted-foreground" />
                    Job Title
                  </Label>
                  <Input
                    id="job-title"
                    placeholder="Recruiting Manager"
                    value={form.job_title}
                    onChange={set("job_title")}
                  />
                </div>

                {/* Company */}
                <div className="space-y-1.5">
                  <Label htmlFor="company" className="text-sm">Company</Label>
                  <Input
                    id="company"
                    placeholder="Acme Corp"
                    value={form.company}
                    onChange={set("company")}
                  />
                </div>

                {/* Location — full width */}
                <div className="space-y-1.5 sm:col-span-2">
                  <Label htmlFor="location" className="text-sm flex items-center gap-1.5">
                    <MapPin className="h-3.5 w-3.5 text-muted-foreground" />
                    Location
                  </Label>
                  <Input
                    id="location"
                    placeholder="San Francisco, CA"
                    value={form.location}
                    onChange={set("location")}
                  />
                </div>
              </div>

              {/* ── Social Links ──────────────────────────────────────── */}
              <Separator className="my-6" />
              <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground mb-4">
                Social Links
              </p>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {/* Website */}
                <div className="space-y-1.5">
                  <Label className="text-sm flex items-center gap-1.5">
                    <Globe className="h-3.5 w-3.5 text-muted-foreground" />
                    Website
                  </Label>
                  <div className="flex rounded-md border border-input focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-0 overflow-hidden">
                    <span className="flex items-center px-3 text-xs text-muted-foreground bg-muted border-r border-input shrink-0 select-none">
                      https://
                    </span>
                    <input
                      className="flex-1 h-9 px-3 py-1 text-sm bg-background outline-none placeholder:text-muted-foreground"
                      placeholder="yoursite.com"
                      value={form.website}
                      onChange={(e) => setForm((f) => ({ ...f, website: e.target.value }))}
                    />
                  </div>
                </div>

                {/* Twitter */}
                <div className="space-y-1.5">
                  <Label className="text-sm flex items-center gap-1.5">
                    <Twitter className="h-3.5 w-3.5 text-muted-foreground" />
                    Twitter / X
                  </Label>
                  <div className="flex rounded-md border border-input focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-0 overflow-hidden">
                    <span className="flex items-center px-3 text-xs text-muted-foreground bg-muted border-r border-input shrink-0 select-none">
                      twitter.com/
                    </span>
                    <input
                      className="flex-1 h-9 px-3 py-1 text-sm bg-background outline-none placeholder:text-muted-foreground"
                      placeholder="handle"
                      value={form.twitter}
                      onChange={(e) => setForm((f) => ({ ...f, twitter: e.target.value }))}
                    />
                  </div>
                </div>

                {/* LinkedIn */}
                <div className="space-y-1.5">
                  <Label className="text-sm flex items-center gap-1.5">
                    <Linkedin className="h-3.5 w-3.5 text-muted-foreground" />
                    LinkedIn
                  </Label>
                  <div className="flex rounded-md border border-input focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-0 overflow-hidden">
                    <span className="flex items-center px-3 text-xs text-muted-foreground bg-muted border-r border-input shrink-0 select-none">
                      linkedin.com/in/
                    </span>
                    <input
                      className="flex-1 h-9 px-3 py-1 text-sm bg-background outline-none placeholder:text-muted-foreground"
                      placeholder="yourname"
                      value={form.linkedin}
                      onChange={(e) => setForm((f) => ({ ...f, linkedin: e.target.value }))}
                    />
                  </div>
                </div>

                {/* GitHub */}
                <div className="space-y-1.5">
                  <Label className="text-sm flex items-center gap-1.5">
                    <Github className="h-3.5 w-3.5 text-muted-foreground" />
                    GitHub
                  </Label>
                  <div className="flex rounded-md border border-input focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-0 overflow-hidden">
                    <span className="flex items-center px-3 text-xs text-muted-foreground bg-muted border-r border-input shrink-0 select-none">
                      github.com/
                    </span>
                    <input
                      className="flex-1 h-9 px-3 py-1 text-sm bg-background outline-none placeholder:text-muted-foreground"
                      placeholder="yourname"
                      value={form.github}
                      onChange={(e) => setForm((f) => ({ ...f, github: e.target.value }))}
                    />
                  </div>
                </div>
              </div>

              {/* ── Plan & Usage ──────────────────────────────────────── */}
              <Separator className="my-6" />
              <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground mb-4">
                Plan & Usage
              </p>

              {/* Plan badges */}
              <div className="flex flex-wrap items-center gap-2 mb-5">
                <Badge variant={isPaid ? "default" : "secondary"} className="gap-1.5 capitalize">
                  {isPaid ? <Crown className="h-3 w-3" /> : <Zap className="h-3 w-3" />}
                  {isPaid ? plan : "Pay As You Go"}
                </Badge>
                <Badge variant="outline" className="gap-1.5 tabular-nums">
                  {totalCredits} credits
                </Badge>
                {profile?.subscription_ends_at && (
                  <span className="text-xs text-muted-foreground">
                    Subscription until{" "}
                    {new Date(profile.subscription_ends_at).toLocaleDateString("en-US", {
                      month: "short",
                      year: "numeric",
                    })}
                  </span>
                )}
              </div>

              {/* 3 stat cards */}
              <div className="grid grid-cols-3 gap-3">
                {!stats ? (
                  <>
                    {[0, 1, 2].map((i) => (
                      <div key={i} className="rounded-lg border border-border/60 p-4 space-y-1.5">
                        <Skeleton className="h-7 w-10" />
                        <Skeleton className="h-3 w-20" />
                      </div>
                    ))}
                  </>
                ) : (
                  <>
                    <div className="rounded-lg border border-border/60 bg-muted/30 p-4">
                      <div className="flex items-center gap-2">
                        <Briefcase className="h-4 w-4 text-muted-foreground shrink-0" />
                        <span className="text-2xl font-semibold tabular-nums text-foreground">{stats.totalJobs}</span>
                      </div>
                      <p className="text-xs text-muted-foreground mt-1">Jobs created</p>
                    </div>
                    <div className="rounded-lg border border-border/60 bg-muted/30 p-4">
                      <div className="flex items-center gap-2">
                        <FileText className="h-4 w-4 text-muted-foreground shrink-0" />
                        <span className="text-2xl font-semibold tabular-nums text-foreground">{stats.totalResumes}</span>
                      </div>
                      <p className="text-xs text-muted-foreground mt-1">Resumes ranked</p>
                    </div>
                    <div className="rounded-lg border border-border/60 bg-muted/30 p-4">
                      <div className="flex items-center gap-2">
                        <Zap className="h-4 w-4 text-muted-foreground shrink-0" />
                        <span className="text-2xl font-semibold tabular-nums text-foreground">{stats.creditsUsed}</span>
                      </div>
                      <p className="text-xs text-muted-foreground mt-1">Credits used</p>
                    </div>
                  </>
                )}
              </div>

              {/* ── Action buttons ────────────────────────────────────── */}
              <Separator className="my-6" />
              <div className="flex items-center justify-end gap-2">
                <Button
                  type="button"
                  variant="outline"
                  onClick={handleCancel}
                  disabled={saving}
                >
                  Cancel
                </Button>
                <Button
                  type="button"
                  onClick={handleSave}
                  disabled={saving}
                  className="gap-1.5"
                >
                  {saving && <Loader2 className="h-4 w-4 animate-spin" />}
                  {saving ? "Saving…" : "Save Changes"}
                </Button>
              </div>

            </CardContent>
          </Card>

          {/* ── Change password card ───────────────────────────────────── */}
          <ChangePasswordCard />

        </div>
      </main>
    </SidebarLayout>
  );
};

export default Profile;

