import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { Shield, Eye, EyeOff } from "lucide-react";

const ChangePasswordCard = () => {
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [saving, setSaving] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const handleChangePassword = async () => {
    if (newPassword.length < 6) {
      toast.error("Password too short — must be at least 6 characters.");
      return;
    }
    if (newPassword !== confirmPassword) {
      toast.error("Passwords don't match");
      return;
    }
    setSaving(true);
    const { error } = await supabase.auth.updateUser({ password: newPassword });
    if (error) {
      toast.error(error.message);
    } else {
      toast.success("Password updated");
      setNewPassword("");
      setConfirmPassword("");
    }
    setSaving(false);
  };

  const passwordsMatch = newPassword && confirmPassword && newPassword === confirmPassword;
  const passwordsMismatch = confirmPassword && newPassword !== confirmPassword;

  return (
    <Card className="overflow-hidden">
      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
          <Shield className="h-4.5 w-4.5 text-primary" />
        </div>
        <div>
          <h3 className="text-sm font-semibold text-foreground">Change Password</h3>
          <p className="text-xs text-muted-foreground">Update your account password.</p>
        </div>
      </div>
      <CardContent className="px-6 pt-3 pb-5 space-y-4">
        <div className="space-y-2">
          <Label htmlFor="new-password" className="text-sm">New password <span className="text-destructive">*</span></Label>
          <p className="text-xs text-muted-foreground">At least 6 characters required</p>
          <div className="relative">
            <Input
              id="new-password"
              type={showPassword ? "text" : "password"}
              placeholder="Min 6 characters"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              className="pr-10"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
              aria-label={showPassword ? "Hide password" : "Show password"}
            >
              {showPassword ? <Eye className="h-4 w-4" /> : <EyeOff className="h-4 w-4" />}
            </button>
          </div>
        </div>
        <div className="space-y-2">
          <Label htmlFor="confirm-password" className="text-sm">Confirm password</Label>
          <Input
            id="confirm-password"
            type={showPassword ? "text" : "password"}
            placeholder="Re-enter password"
            value={confirmPassword}
            onChange={(e) => setConfirmPassword(e.target.value)}
            className={passwordsMismatch ? "border-destructive focus-visible:ring-destructive" : passwordsMatch ? "border-primary/50 focus-visible:ring-primary" : ""}
          />
          {passwordsMismatch && (
            <p className="text-xs text-destructive">Passwords don't match.</p>
          )}
          {passwordsMatch && (
            <p className="text-xs text-primary">Passwords match ✓</p>
          )}
        </div>
        <Button
          onClick={handleChangePassword}
          disabled={saving || !newPassword || !passwordsMatch}
          className="w-full"
        >
          {saving ? "Updating…" : "Update password"}
        </Button>
      </CardContent>
    </Card>
  );
};

export default ChangePasswordCard;

if (isLoading) {
  return (
    <SidebarLayout>
      <main className="w-full max-w-3xl mx-auto px-6 sm:px-8 lg:px-10 py-8">
        <Skeleton className="h-8 w-32 mb-2" />
        <Skeleton className="h-4 w-64 mb-8" />
        <Card className="border border-border/60"><CardContent className="p-6 space-y-6">
          <div className="flex items-center gap-5">
            <Skeleton className="h-20 w-20 rounded-full" />
            <div className="space-y-2"><Skeleton className="h-4 w-24" /><Skeleton className="h-3 w-36" /></div>
          </div>
          {[1, 2, 3].map((i) => (<div key={i}><Separator className="my-6" /><div className="grid grid-cols-2 gap-4">{[1, 2].map((j) => (<div key={j} className="space-y-2"><Skeleton className="h-4 w-20" /><Skeleton className="h-9 w-full" /></div>))}</div></div>))}
        </CardContent></Card>
      </main>
    </SidebarLayout>
  );
}

return (
  <SidebarLayout>
    <main className="w-full max-w-3xl mx-auto px-6 sm:px-8 lg:px-10 py-8">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-2xl font-bold text-foreground">Profile</h1>
        <p className="text-sm text-muted-foreground mt-1">
          Manage your personal information and how others see you.
        </p>
      </div>

      <Card className="border border-border/60 shadow-sm">
        <CardContent className="p-6 sm:p-8">

          {/* ── Avatar ─────────────────────────────────────────── */}
          <div className="flex items-center gap-5">
            <div className="relative group shrink-0">
              {form.avatar_url ? (
                <img src={form.avatar_url} alt="Avatar" className="h-20 w-20 rounded-full object-cover border-2 border-border" />
              ) : (
                <div className="h-20 w-20 rounded-full bg-primary text-primary-foreground text-xl font-bold flex items-center justify-center border-2 border-border select-none">
                  {getInitials(user?.email, form.full_name)}
