  Eye,
  EyeOff,
} from "lucide-react";

// ─── helpers ──────────────────────────────────────────────────────────────────

function getInitials(email?: string | null, fullName?: string | null): string {
  if (fullName) {
    const parts = fullName.trim().split(/\s+/);
    if (parts.length >= 2) return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
    return parts[0][0]?.toUpperCase() ?? "?";
  }
  if (!email) return "?";
  const local = email.split("@")[0];
  const parts = local.split(/[._-]/);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  return local[0]?.toUpperCase() ?? "?";
}

// ─── types ────────────────────────────────────────────────────────────────────

interface ProfileFields {
  full_name: string | null;
  username: string | null;
  bio: string | null;
  avatar_url: string | null;
  job_title: string | null;
  company: string | null;
  location: string | null;
  website: string | null;
  twitter: string | null;
  linkedin: string | null;
  github: string | null;
}

interface FormState {
  full_name: string;
  username: string;
  bio: string;
  avatar_url: string;
  job_title: string;
  company: string;
  location: string;
  website: string;
  twitter: string;
  linkedin: string;
  github: string;
}

const EMPTY: FormState = {
  full_name: "", username: "", bio: "", avatar_url: "",
  job_title: "", company: "", location: "",
  website: "", twitter: "", linkedin: "", github: "",
};

function toForm(p: ProfileFields): FormState {
  return Object.fromEntries(
    Object.entries(EMPTY).map(([k]) => [k, (p as Record<string, string | null>)[k] ?? ""])
  ) as FormState;
}

// ─── prefix input ─────────────────────────────────────────────────────────────

function PrefixInput({
  prefix, value, onChange, placeholder,
}: {
  prefix: string;
  value: string;
  onChange: (v: string) => void;
  placeholder: string;
}) {
  return (
    <div className="flex rounded-md border border-input focus-within:ring-2 focus-within:ring-ring focus-within:border-ring overflow-hidden transition-shadow">
      <span className="flex items-center px-3 text-xs text-muted-foreground bg-muted border-r border-input shrink-0 select-none">
        {prefix}
      </span>
      <input
        className="flex-1 h-9 px-3 py-1 text-sm bg-background outline-none placeholder:text-muted-foreground min-w-0"
        placeholder={placeholder}
        value={value}
        onChange={(e) => onChange(e.target.value)}
      />
    </div>
  );
}

// ─── component ────────────────────────────────────────────────────────────────

const Profile = () => {
  const { user, refreshProfile } = useAuth();
  const queryClient = useQueryClient();
  const fileRef = useRef<HTMLInputElement>(null);

  const [form, setForm] = useState<FormState>(EMPTY);
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);

  // Password
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [savingPw, setSavingPw] = useState(false);
  const [showPw, setShowPw] = useState(false);
  const pwMatch = newPassword && confirmPassword && newPassword === confirmPassword;
  const pwMismatch = confirmPassword.length > 0 && newPassword !== confirmPassword;

  // ── fetch profile fields ────────────────────────────────────────────────
  const { data: loaded, isLoading } = useQuery<ProfileFields>({
    queryKey: ["profileFull", user?.id],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("profiles")
        .select("full_name, username, bio, avatar_url, job_title, company, location, website, twitter, linkedin, github")
        .eq("user_id", user!.id)
        .single();
      if (error) throw error;
      return data as ProfileFields;
    },
    enabled: !!user,
    staleTime: 5 * 60 * 1000,
  });

  useEffect(() => {
    if (loaded) setForm(toForm(loaded));
  }, [loaded]);

  const set = (key: keyof FormState) => (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>
    setForm((f) => ({ ...f, [key]: e.target.value }));

  // ── avatar ──────────────────────────────────────────────────────────────
  const handleAvatar = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !user) return;
    if (file.size > 5 * 1024 * 1024) { toast.error("Max 5 MB"); return; }
    if (!file.type.startsWith("image/")) { toast.error("Images only"); return; }

    setUploading(true);
    try {
      const ext = file.name.split(".").pop();
      const path = `${user.id}/avatar.${ext}`;
      const { error } = await supabase.storage.from("avatars").upload(path, file, { upsert: true, contentType: file.type });
      if (error) throw error;
      const { data: u } = supabase.storage.from("avatars").getPublicUrl(path);
      const url = u.publicUrl + `?t=${Date.now()}`;
      await (supabase as any).from("profiles").update({ avatar_url: url }).eq("user_id", user.id);
      setForm((f) => ({ ...f, avatar_url: url }));
      queryClient.invalidateQueries({ queryKey: ["profileFull", user.id] });
      toast.success("Photo updated");
    } catch { toast.error("Upload failed"); }
    finally { setUploading(false); if (fileRef.current) fileRef.current.value = ""; }
  };

  const removeAvatar = async () => {
    if (!user) return;
    try { await supabase.storage.from("avatars").remove([`${user.id}/avatar.jpg`, `${user.id}/avatar.png`, `${user.id}/avatar.webp`]); } catch {}
    setForm((f) => ({ ...f, avatar_url: "" }));
    await (supabase as any).from("profiles").update({ avatar_url: null }).eq("user_id", user.id);
    queryClient.invalidateQueries({ queryKey: ["profileFull", user.id] });
    toast.success("Photo removed");
  };

  // ── save / cancel ───────────────────────────────────────────────────────
  const handleSave = async () => {
    if (!user) return;
    setSaving(true);
    try {
      const payload = Object.fromEntries(
        Object.entries(form).map(([k, v]) => [k, v.trim() || null])
      );
      const { error } = await (supabase as any).from("profiles").update(payload).eq("user_id", user.id);
      if (error) throw error;
      await refreshProfile();
      queryClient.invalidateQueries({ queryKey: ["profileFull", user.id] });
      toast.success("Profile saved");
    } catch { toast.error("Failed to save"); }
    finally { setSaving(false); }
  };

  const handleCancel = () => { if (loaded) setForm(toForm(loaded)); else setForm(EMPTY); };

  const handleChangePassword = async () => {
    if (newPassword.length < 6) { toast.error("Password must be at least 6 characters"); return; }
    if (!pwMatch) { toast.error("Passwords don't match"); return; }
    setSavingPw(true);
    const { error } = await supabase.auth.updateUser({ password: newPassword });
    if (error) toast.error(error.message);
    else { toast.success("Password updated"); setNewPassword(""); setConfirmPassword(""); }
    setSavingPw(false);
  };

  // ─── render ─────────────────────────────────────────────────────────────
  if (isLoading) {
    return (
      <SidebarLayout>
        <main className="w-full max-w-3xl mx-auto px-6 sm:px-8 lg:px-10 py-8">
          <Skeleton className="h-8 w-32 mb-2" />
          <Skeleton className="h-4 w-64 mb-8" />
          <Card className="border border-border/60"><CardContent className="p-6 space-y-6">
            <div className="flex items-center gap-5">
              <Skeleton className="h-20 w-20 rounded-full" />
              <div className="space-y-2"><Skeleton className="h-4 w-24" /><Skeleton className="h-3 w-36" /></div>
            </div>
            {[1, 2, 3].map((i) => (<div key={i}><Separator className="my-6" /><div className="grid grid-cols-2 gap-4">{[1, 2].map((j) => (<div key={j} className="space-y-2"><Skeleton className="h-4 w-20" /><Skeleton className="h-9 w-full" /></div>))}</div></div>))}
          </CardContent></Card>
        </main>
      </SidebarLayout>
    );
  }

  return (
    <SidebarLayout>
      <main className="w-full max-w-3xl mx-auto px-6 sm:px-8 lg:px-10 py-8">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-2xl font-bold text-foreground">Profile</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Manage your personal information and how others see you.
          </p>
        </div>

        <Card className="border border-border/60 shadow-sm">
          <CardContent className="p-6 sm:p-8">

            {/* ── Avatar ─────────────────────────────────────────── */}
            <div className="flex items-center gap-5">
              <div className="relative group shrink-0">
                {form.avatar_url ? (
                  <img src={form.avatar_url} alt="Avatar" className="h-20 w-20 rounded-full object-cover border-2 border-border" />
                ) : (
                  <div className="h-20 w-20 rounded-full bg-primary text-primary-foreground text-xl font-bold flex items-center justify-center border-2 border-border select-none">
                    {getInitials(user?.email, form.full_name)}
                  </div>
                )}
                {/* Camera overlay */}
                <button
                  type="button"
                  onClick={() => fileRef.current?.click()}
                  disabled={uploading}
                  className="absolute inset-0 rounded-full bg-black/0 group-hover:bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all cursor-pointer"
                >
                  {uploading
                    ? <Loader2 className="h-5 w-5 text-white animate-spin" />
                    : <Camera className="h-5 w-5 text-white" />}
                </button>
              </div>
              <div>
                <p className="text-sm font-medium text-foreground">Profile photo</p>
                <p className="text-xs text-muted-foreground mt-0.5">
                  JPG, PNG or WebP. Max 5 MB.
                </p>
                <div className="flex items-center gap-2 mt-2">
                  <Button type="button" variant="outline" size="sm" className="h-7 text-xs" onClick={() => fileRef.current?.click()} disabled={uploading}>
                    {uploading ? "Uploading..." : "Upload"}
                  </Button>
                  {form.avatar_url && (
                    <Button type="button" variant="ghost" size="sm" className="h-7 text-xs text-muted-foreground hover:text-destructive" onClick={removeAvatar}>
                      <Trash2 className="h-3 w-3 mr-1" /> Remove
                    </Button>
                  )}
                </div>
              </div>
              <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={handleAvatar} />
            </div>

            {/* ── Personal Information ────────────────────────────── */}
            <Separator className="my-8" />
            <div className="mb-5">
              <h3 className="text-sm font-semibold text-foreground">Personal Information</h3>
              <p className="text-xs text-muted-foreground mt-0.5">Your name and contact details.</p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-4">
              <div className="space-y-2">
                <Label htmlFor="full-name" className="text-sm font-medium">Full Name</Label>
                <Input id="full-name" placeholder="Jane Smith" value={form.full_name} onChange={set("full_name")} />
              </div>
              <div className="space-y-2">
                <Label htmlFor="username" className="text-sm font-medium">Username</Label>
                <PrefixInput prefix="@" value={form.username} onChange={(v) => setForm((f) => ({ ...f, username: v }))} placeholder="janesmith" />
              </div>
              <div className="space-y-2 sm:col-span-2">
                <Label htmlFor="bio" className="text-sm font-medium">Bio</Label>
                <Textarea
                  id="bio"
                  placeholder="Write a short bio about yourself..."
                  value={form.bio}
                  onChange={set("bio")}
                  maxLength={160}
                  rows={3}
                  className="resize-none"
                />
                <p className="text-[11px] text-muted-foreground text-right tabular-nums">{form.bio.length}/160</p>
              </div>
            </div>

            {/* ── Work Details ────────────────────────────────────── */}
            <Separator className="my-8" />
            <div className="mb-5">
              <h3 className="text-sm font-semibold text-foreground">Work Details</h3>
              <p className="text-xs text-muted-foreground mt-0.5">Your current role and organization.</p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-4">
              <div className="space-y-2">
                <Label className="text-sm font-medium flex items-center gap-1.5">
                  <Briefcase className="h-3.5 w-3.5 text-muted-foreground" /> Job Title
                </Label>
                <Input placeholder="Recruiting Manager" value={form.job_title} onChange={set("job_title")} />
              </div>
              <div className="space-y-2">
                <Label className="text-sm font-medium flex items-center gap-1.5">
                  <Building2 className="h-3.5 w-3.5 text-muted-foreground" /> Company
                </Label>
                <Input placeholder="Acme Corp" value={form.company} onChange={set("company")} />
              </div>
              <div className="space-y-2 sm:col-span-2">
                <Label className="text-sm font-medium flex items-center gap-1.5">
                  <MapPin className="h-3.5 w-3.5 text-muted-foreground" /> Location
                </Label>
                <Input placeholder="San Francisco, CA" value={form.location} onChange={set("location")} />
              </div>
            </div>

            {/* ── Social Links ────────────────────────────────────── */}
            <Separator className="my-8" />
            <div className="mb-5">
              <h3 className="text-sm font-semibold text-foreground">Social Links</h3>
              <p className="text-xs text-muted-foreground mt-0.5">Connect your online profiles.</p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-4">
              <div className="space-y-2">
                <Label className="text-sm font-medium flex items-center gap-1.5">
                  <Globe className="h-3.5 w-3.5 text-muted-foreground" /> Website
                </Label>
                <PrefixInput prefix="https://" value={form.website} onChange={(v) => setForm((f) => ({ ...f, website: v }))} placeholder="yoursite.com" />
              </div>
              <div className="space-y-2">
                <Label className="text-sm font-medium flex items-center gap-1.5">
                  <Twitter className="h-3.5 w-3.5 text-muted-foreground" /> Twitter
                </Label>
                <PrefixInput prefix="twitter.com/" value={form.twitter} onChange={(v) => setForm((f) => ({ ...f, twitter: v }))} placeholder="handle" />
              </div>
              <div className="space-y-2">
                <Label className="text-sm font-medium flex items-center gap-1.5">
                  <Linkedin className="h-3.5 w-3.5 text-muted-foreground" /> LinkedIn
                </Label>
                <PrefixInput prefix="linkedin.com/in/" value={form.linkedin} onChange={(v) => setForm((f) => ({ ...f, linkedin: v }))} placeholder="yourname" />
              </div>
              <div className="space-y-2">
                <Label className="text-sm font-medium flex items-center gap-1.5">
                  <Github className="h-3.5 w-3.5 text-muted-foreground" /> GitHub
                </Label>
                <PrefixInput prefix="github.com/" value={form.github} onChange={(v) => setForm((f) => ({ ...f, github: v }))} placeholder="yourname" />
              </div>
            </div>

            {/* ── Actions ─────────────────────────────────────────── */}
            <div className="flex items-center justify-end gap-3 mt-8 pt-6 border-t border-border">
              <Button type="button" variant="outline" onClick={handleCancel} disabled={saving}>
                Cancel
              </Button>
              <Button type="button" onClick={handleSave} disabled={saving} className="min-w-[120px]">
                {saving ? <><Loader2 className="h-4 w-4 animate-spin mr-1.5" /> Saving...</> : "Save Changes"}
              </Button>
            </div>

          </CardContent>
        </Card>
      </main>
    </SidebarLayout>
  );
};

export default Profile;

