import {
  Briefcase,
  Home,
  Settings,
  CreditCard,
  Users,
  CheckSquare,
  Activity,
  Globe,
  Layers,
  Megaphone,
  FileText,
  Plug,
  BarChart3,
  Building2,
  Bookmark,
} from "lucide-react";
import {
  Sidebar,
  SidebarContent,
  SidebarHeader,
  SidebarMenu,
