1	import { Shield, ShieldAlert, ShieldCheck } from "lucide-react";
2	import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
3	import { cn } from "@/lib/utils";
4	
5	interface AuthenticityData {
6	  authenticity_score: number;
7	  risk_level: "low" | "medium" | "high";
8	  flags: string[];
9	  summary: string;
10	}
11	
12	interface AuthenticityBadgeProps {
13	  data: AuthenticityData | null | undefined;
14	  className?: string;
15	  showScore?: boolean;
16	}
17	
18	const getRiskConfig = (riskLevel: "low" | "medium" | "high") => {
19	  switch (riskLevel) {
20	    case "low":
21	      return {
22	        icon: ShieldCheck,
23	        label: "Authentic",
24	        badgeClass: "bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-700",
25	        iconClass: "text-emerald-500",
26	      };
27	    case "medium":
28	      return {
29	        icon: Shield,
30	        label: "Review",
31	        badgeClass: "bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-700",
32	        iconClass: "text-amber-500",
33	      };
34	    case "high":
35	      return {
36	        icon: ShieldAlert,
37	        label: "Risk",
38	        badgeClass: "bg-red-50 text-red-700 border-red-200 dark:bg-red-900/20 dark:text-red-400 dark:border-red-700",
39	        iconClass: "text-red-500",
40	      };
41	  }
42	};
43	
44	const AuthenticityBadge = ({ data, className, showScore = false }: AuthenticityBadgeProps) => {
45	  if (!data) return null;
46	
47	  const config = getRiskConfig(data.risk_level);
48	  const Icon = config.icon;
49	
50	  return (
51	    <TooltipProvider delayDuration={200}>
52	      <Tooltip>
53	        <TooltipTrigger asChild>
54	          <span
55	            className={cn(
56	              "inline-flex items-center gap-1 px-1.5 py-0.5 rounded border text-[11px] font-medium cursor-default select-none",
57	              config.badgeClass,
58	              className
59	            )}
60	          >
61	            <Icon className={cn("h-3 w-3 shrink-0", config.iconClass)} />
62	            {config.label}
63	            {showScore && (
64	              <span className="tabular-nums ml-0.5">{data.authenticity_score}%</span>
65	            )}
66	          </span>
67	        </TooltipTrigger>
68	        <TooltipContent side="top" className="max-w-xs">
69	          <p className="text-xs font-medium mb-1">Authenticity: {data.authenticity_score}%</p>
70	          <p className="text-xs text-muted-foreground">{data.summary}</p>
71	          {data.flags.length > 0 && (
72	            <ul className="mt-1.5 space-y-0.5">
