import { Shield, ShieldAlert, ShieldCheck } from "lucide-react";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

interface AuthenticityData {
  authenticity_score: number;
  risk_level: "low" | "medium" | "high";
  flags: string[];
  summary: string;
}

interface AuthenticityBadgeProps {
  data: AuthenticityData | null | undefined;
  className?: string;
  showScore?: boolean;
}

const getRiskConfig = (riskLevel: "low" | "medium" | "high") => {
  switch (riskLevel) {
    case "low":
      return {
        icon: ShieldCheck,
        label: "Authentic",
        badgeClass: "bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-700",
        iconClass: "text-emerald-500",
      };
    case "medium":
      return {
        icon: Shield,
        label: "Review",
        badgeClass: "bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-700",
        iconClass: "text-amber-500",
      };
    case "high":
      return {
        icon: ShieldAlert,
        label: "Risk",
        badgeClass: "bg-red-50 text-red-700 border-red-200 dark:bg-red-900/20 dark:text-red-400 dark:border-red-700",
        iconClass: "text-red-500",
      };
  }
};

const AuthenticityBadge = ({ data, className, showScore = false }: AuthenticityBadgeProps) => {
  if (!data) return null;

  const config = getRiskConfig(data.risk_level);
  const Icon = config.icon;

  return (
    <TooltipProvider delayDuration={200}>
      <Tooltip>
        <TooltipTrigger asChild>
          <span
            className={cn(
              "inline-flex items-center gap-1 px-1.5 py-0.5 rounded border text-[11px] font-medium cursor-default select-none",
              config.badgeClass,
              className
            )}
          >
            <Icon className={cn("h-3 w-3 shrink-0", config.iconClass)} />
            {config.label}
            {showScore && (
              <span className="tabular-nums ml-0.5">{data.authenticity_score}%</span>
            )}
          </span>
        </TooltipTrigger>
        <TooltipContent side="top" className="max-w-xs">
          <p className="text-xs font-medium mb-1">Authenticity: {data.authenticity_score}%</p>
          <p className="text-xs text-muted-foreground">{data.summary}</p>
          {data.flags.length > 0 && (
            <ul className="mt-1.5 space-y-0.5">
              {data.flags.slice(0, 3).map((flag, i) => (
                <li key={i} className="text-xs text-destructive flex items-start gap-1">
                  <span className="shrink-0 mt-0.5">•</span>
                  {flag}
                </li>
              ))}
            </ul>
          )}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
};

export default AuthenticityBadge;

-- ─── Authenticity analysis on results ───────────────────────────────────────
ALTER TABLE results ADD COLUMN IF NOT EXISTS authenticity_json jsonb;

-- ─── Stage automations ────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS stage_automations (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  team_id     uuid NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  stage_name  text NOT NULL,
  action_type text NOT NULL CHECK (action_type IN ('send_email', 'add_tag', 'assign_member', 'webhook')),
  action_config jsonb NOT NULL DEFAULT '{}',
  is_active   boolean NOT NULL DEFAULT true,
  created_at  timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE stage_automations ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Team members can read their automations"
  ON stage_automations FOR SELECT
  USING (
    team_id IN (
      SELECT team_id FROM team_members WHERE user_id = auth.uid()
    )
  );

CREATE POLICY "Team admins/owners can manage automations"
  ON stage_automations FOR ALL
  USING (
    team_id IN (
      SELECT team_id FROM team_members
      WHERE user_id = auth.uid() AND role IN ('owner', 'admin')
    )
  );

-- ─── Talent pool ─────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS talent_pool (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  team_id         uuid NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  resume_id       uuid NOT NULL REFERENCES resumes(id) ON DELETE CASCADE,
  original_job_id uuid REFERENCES jobs(id) ON DELETE SET NULL,
  added_by        uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  notes           text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  UNIQUE (team_id, resume_id)
);

ALTER TABLE talent_pool ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Team members can read talent pool"
  ON talent_pool FOR SELECT
  USING (
    team_id IN (
      SELECT team_id FROM team_members WHERE user_id = auth.uid()
    )
  );

CREATE POLICY "Team members can insert into talent pool"
  ON talent_pool FOR INSERT
  WITH CHECK (
    team_id IN (
      SELECT team_id FROM team_members WHERE user_id = auth.uid()
    )
    AND added_by = auth.uid()
  );

CREATE POLICY "Team admins/owners can delete from talent pool"
  ON talent_pool FOR DELETE
  USING (
    team_id IN (
      SELECT team_id FROM team_members
      WHERE user_id = auth.uid() AND role IN ('owner', 'admin')
    )
    OR added_by = auth.uid()
  );

CREATE INDEX IF NOT EXISTS talent_pool_team_id_idx ON talent_pool (team_id);
CREATE INDEX IF NOT EXISTS talent_pool_resume_id_idx ON talent_pool (resume_id);

