import { useState } from "react";
import { Bookmark, BookmarkCheck, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

interface AddToPoolButtonProps {
  resumeId: string;
  jobId: string;
  teamId: string;
  isInPool?: boolean;
  onPoolChange?: (inPool: boolean) => void;
  size?: "sm" | "default";
  variant?: "ghost" | "outline" | "default";
}

const AddToPoolButton = ({
  resumeId,
  jobId,
  teamId,
  isInPool = false,
  onPoolChange,
  size = "sm",
  variant = "outline",
}: AddToPoolButtonProps) => {
  const { user } = useAuth();
  const [inPool, setInPool] = useState(isInPool);
  const [loading, setLoading] = useState(false);

  const handleToggle = async () => {
    if (!user) {
      toast.error("You must be logged in");
      return;
    }

    setLoading(true);
    try {
      if (inPool) {
        // Remove from pool
        const { error } = await (supabase as any)
          .from("talent_pool")
          .delete()
          .eq("resume_id", resumeId)
          .eq("team_id", teamId);

        if (error) throw error;
        setInPool(false);
        onPoolChange?.(false);
        toast.success("Removed from talent pool");
      } else {
        // Add to pool
        const { error } = await (supabase as any)
          .from("talent_pool")
          .insert({
            resume_id: resumeId,
            job_id: jobId,
            team_id: teamId,
            added_by: user.id,
          });

        if (error) {
          if (error.code === "23505") {
            // Already in pool (unique constraint)
            setInPool(true);
            onPoolChange?.(true);
            toast.info("Already in talent pool");
            return;
          }
          throw error;
        }
        setInPool(true);
        onPoolChange?.(true);
        toast.success("Added to talent pool");
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to update talent pool";
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <TooltipProvider delayDuration={300}>
      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            variant={inPool ? "default" : variant}
            size={size}
            className={`h-8 gap-1.5 text-xs ${inPool ? "bg-primary/90" : ""}`}
            onClick={handleToggle}
            disabled={loading}
          >
            {loading ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : inPool ? (
              <BookmarkCheck className="h-3.5 w-3.5" />
            ) : (
              <Bookmark className="h-3.5 w-3.5" />
            )}
            {inPool ? "In Pool" : "Save to Pool"}
          </Button>
        </TooltipTrigger>
        <TooltipContent>
          {inPool ? "Remove from talent pool" : "Save to talent pool for future roles"}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
};

export default AddToPoolButton;

