import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useNavigate } from "react-router-dom";
import {
  Bookmark,
  Search,
  MapPin,
  Briefcase,
  Trash2,
  Loader2,
  StickyNote,
  AlertCircle,
  RefreshCw,
} from "lucide-react";
import SidebarLayout from "@/components/SidebarLayout";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { useTeam } from "@/hooks/useTeam";
import AuthenticityBadge from "@/components/candidate/AuthenticityBadge";
import { format } from "date-fns";

interface PoolEntry {
  id: string;
  resume_id: string;
  original_job_id: string | null;
  added_by: string;
  notes: string | null;
  created_at: string;
  resume: {
    id: string;
    filename: string;
    candidate_name: string | null;
    candidate_email: string | null;
    parsed_json: Record<string, unknown> | null;
    job_id: string;
  } | null;
  original_job: {
    id: string;
    title: string | null;
  } | null;
  result: {
    overall_score: number;
    skill_score: number;
    experience_score: number;
    authenticity_json: {
      authenticity_score: number;
      risk_level: "low" | "medium" | "high";
      flags: string[];
      summary: string;
    } | null;
  } | null;
}

const getScoreColor = (score: number) => {
  if (score >= 70) return "text-emerald-600 dark:text-emerald-400";
  if (score >= 40) return "text-amber-600 dark:text-amber-400";
  return "text-red-600 dark:text-red-400";
};

function PoolSkeleton() {
  return (
    <div className="space-y-0.5">
      {[1, 2, 3, 4, 5].map((i) => (
        <div key={i} className="flex items-center gap-4 px-4 py-3 border-b border-border">
          <Skeleton className="h-4 w-40" />
          <Skeleton className="h-4 w-28" />
          <Skeleton className="h-4 w-20" />
          <Skeleton className="h-4 w-16 ml-auto" />
        </div>
      ))}
    </div>
  );
}

const TalentPool = () => {
  const navigate = useNavigate();
  const { team } = useTeam();
  const qc = useQueryClient();

  const [search, setSearch] = useState("");
  const [removingId, setRemovingId] = useState<string | null>(null);
  const [notesEntry, setNotesEntry] = useState<PoolEntry | null>(null);
  const [notesText, setNotesText] = useState("");
  const [savingNotes, setSavingNotes] = useState(false);

  const { data: poolEntries = [], isLoading, error, refetch } = useQuery<PoolEntry[]>({
    queryKey: ["talent_pool", team?.id],
    queryFn: async () => {
      if (!team?.id) return [];
      // Fetch pool entries (flat, no joins — avoids FK hint issues)
      const { data: poolData, error: poolError } = await (supabase as any)
        .from("talent_pool")
        .select("id, resume_id, original_job_id, added_by, notes, created_at")
        .eq("team_id", team.id)
        .order("created_at", { ascending: false });

      if (poolError) throw poolError;
      if (!poolData || poolData.length === 0) return [];

      const resumeIds = poolData.map((e: any) => e.resume_id);
      const jobIds = poolData.map((e: any) => e.original_job_id).filter(Boolean);

      // Fetch resumes, jobs, results in parallel
      const [resumesRes, jobsRes, resultsRes] = await Promise.all([
        (supabase as any).from("resumes").select("id, filename, candidate_name, candidate_email, parsed_json, job_id").in("id", resumeIds),
        jobIds.length > 0 ? (supabase as any).from("jobs").select("id, title").in("id", jobIds) : { data: [] },
        (supabase as any).from("results").select("resume_id, overall_score, skill_score, experience_score, authenticity_json").in("resume_id", resumeIds),
      ]);

      const resumeMap: Record<string, any> = {};
      (resumesRes.data ?? []).forEach((r: any) => { resumeMap[r.id] = r; });
      const jobMap: Record<string, any> = {};
      (jobsRes.data ?? []).forEach((j: any) => { jobMap[j.id] = j; });
      const resultMap: Record<string, any> = {};
      (resultsRes.data ?? []).forEach((r: any) => { resultMap[r.resume_id] = r; });

      return poolData.map((e: any) => ({
        ...e,
        resume: resumeMap[e.resume_id] ?? null,
        original_job: e.original_job_id ? (jobMap[e.original_job_id] ?? null) : null,
        result: resultMap[e.resume_id] ?? null,
      }));
    },
    enabled: !!team?.id,
    staleTime: 30_000,
  });

  const handleRemove = async (entryId: string) => {
    setRemovingId(entryId);
    try {
      const { error } = await (supabase as any)
        .from("talent_pool")
        .delete()
        .eq("id", entryId);
      if (error) throw error;
      qc.invalidateQueries({ queryKey: ["talent_pool", team?.id] });
      toast.success("Removed from talent pool");
    } catch {
      toast.error("Failed to remove from pool");
    } finally {
      setRemovingId(null);
    }
  };

  const openNotes = (entry: PoolEntry) => {
    setNotesEntry(entry);
    setNotesText(entry.notes ?? "");
  };

  const handleSaveNotes = async () => {
    if (!notesEntry) return;
    setSavingNotes(true);
    try {
      const { error } = await (supabase as any)
        .from("talent_pool")
        .update({ notes: notesText.trim() || null })
        .eq("id", notesEntry.id);
      if (error) throw error;
      qc.invalidateQueries({ queryKey: ["talent_pool", team?.id] });
      toast.success("Notes saved");
      setNotesEntry(null);
    } catch {
      toast.error("Failed to save notes");
    } finally {
      setSavingNotes(false);
    }
  };

  const filtered = poolEntries.filter((entry) => {
    if (!search) return true;
    const q = search.toLowerCase();
    const name = (entry.resume?.candidate_name ?? entry.resume?.filename ?? "").toLowerCase();
    const location = String((entry.resume?.parsed_json as Record<string, unknown>)?.location ?? "").toLowerCase();
    const jobTitle = (entry.original_job?.title ?? "").toLowerCase();
    return name.includes(q) || location.includes(q) || jobTitle.includes(q);
  });

  if (!team) {
    return (
      <SidebarLayout>
        <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
          <div className="flex flex-col items-center justify-center py-16 space-y-3 text-center">
            <div className="rounded-xl bg-muted/50 p-4">
              <Bookmark className="h-8 w-8 text-muted-foreground/40" />
            </div>
            <h2 className="text-base font-semibold">No Team Found</h2>
            <p className="text-sm text-muted-foreground max-w-sm">
              Create or join a team to use the talent pool feature.
            </p>
            <Button size="sm" onClick={() => navigate("/team")}>
              Go to Team
            </Button>
          </div>
        </main>
      </SidebarLayout>
    );
  }

  return (
    <SidebarLayout>
      <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
        {/* Header */}
        <div className="flex items-center justify-between mb-1">
          <h1 className="text-2xl font-bold text-foreground">Talent Pool</h1>
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8"
            onClick={() => refetch()}
            disabled={isLoading}
            aria-label="Refresh"
          >
            <RefreshCw className={`h-4 w-4 ${isLoading ? "animate-spin" : ""}`} />
          </Button>
        </div>
        <p className="text-sm text-muted-foreground mb-6">
          Candidates saved for future roles across your team.
        </p>

        {/* Search */}
        <div className="relative mb-4">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
