                  className="w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm font-medium shadow-sm placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
                />
                <textarea
                  placeholder="Paste the full job description here…"
                  value={jobDescription}
                  onFocus={() => { if (!isAuthenticated) { onAuthRequired(); } }}
                  onChange={(e) => { if (!isAuthenticated) { onAuthRequired(); return; } setJobDescription(e.target.value); }}
                  className="flex-1 min-h-[200px] w-full resize-none rounded-md border border-input bg-transparent px-3 py-2 text-sm shadow-sm placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
                />
                </div>
              )}
            </CardContent>
          </Card>

          {/* RIGHT column — upload card + inbox email card, drives the row height */}
          <div className="flex flex-col gap-4">

            {/* Upload card */}
            <Card>
              <CardHeader className="pb-3">
                <div className="flex items-center justify-between">
                  <CardTitle className="text-sm font-semibold">
                    {isExistingJob ? "Add More Resumes" : "Upload Resumes"}
                  </CardTitle>
                  <div className="flex items-center gap-2">
                    {isExistingJob && existingResumes.length > 0 && (
                      <Badge variant="secondary" className="text-[11px]">
                        {existingResumes.length} uploaded
                      </Badge>
                    )}
                  </div>
                </div>
              </CardHeader>
              <CardContent className="space-y-3">
                <div
                  className={`border-2 border-dashed rounded-lg p-6 text-center cursor-pointer transition-all duration-300 flex flex-col items-center justify-center ${
                    dragOver ? "border-primary bg-primary/5 scale-[1.01]" : "border-border hover:border-primary/50 hover:bg-primary/[0.02]"
                  }`}
                  onDragOver={(e) => { e.preventDefault(); if (!isAuthenticated) return; setDragOver(true); }}
                  onDragLeave={() => setDragOver(false)}
                  onDrop={(e) => { if (!isAuthenticated) { e.preventDefault(); onAuthRequired(); return; } handleFileDrop(e); }}
                  onClick={() => { if (!isAuthenticated) { onAuthRequired(); return; } document.getElementById("file-input")?.click(); }}
                >
                  <div className="w-10 h-10 rounded-lg bg-muted flex items-center justify-center mb-2.5">
                    <Upload className="h-5 w-5 text-primary" />
                  </div>
                  <p className="text-sm font-medium text-foreground mb-1">Drop resumes here or click to select</p>
                  <p className="text-xs text-muted-foreground">PDF, DOCX, DOC, RTF, TXT, ZIP · Max {maxResumes} files · {maxFileSizeMb}MB each</p>
                  <input id="file-input" type="file" className="hidden" multiple accept=".pdf,.docx,.doc,.rtf,.txt,.zip" onChange={handleFileSelect} />
                </div>
                {files.length > 0 && (
                  <div className="space-y-1.5">
                    {/* Select all / deselect when auto-rank OFF */}
                    {profile?.auto_rank_enabled === false && files.length > 1 && !ranking && (
                      <button
                        className="text-xs text-primary hover:text-primary/80 transition-colors"
                        onClick={() => {
                          if (selectedFileIndexes.size === files.length) setSelectedFileIndexes(new Set());
                          else setSelectedFileIndexes(new Set(files.map((_, i) => i)));
                        }}
                      >
                        {selectedFileIndexes.size === files.length ? "Deselect all" : "Select all"}
                      </button>
                    )}
                    {files.map((f, i) => {
                      const isProcessing = rankingFilesRef.current.has(f.name) && ranking;
                      const isManualMode = profile?.auto_rank_enabled === false && !ranking;
                      return (
                        <div key={i} className="flex items-center justify-between bg-secondary/50 rounded-md px-3 py-2 animate-fade-in">
                          <div className="flex items-center gap-2 text-sm">
                            {isManualMode ? (
                              <Checkbox
                                checked={selectedFileIndexes.has(i)}
                                onCheckedChange={(checked) => {
                                  setSelectedFileIndexes(prev => {
                                    const next = new Set(prev);
                                    if (checked) next.add(i); else next.delete(i);
                                    return next;
                                  });
                                }}
                              />
                            ) : isProcessing ? (
                              <Loader2 className="h-4 w-4 text-primary animate-spin" />
                            ) : (
                              <FileText className="h-4 w-4 text-muted-foreground" />
                            )}
                            <span className={isProcessing ? "text-muted-foreground" : ""}>{f.name}</span>
                            {!isProcessing && ranking && <Badge variant="outline" className="text-[11px]">Queued</Badge>}
                          </div>
                          {!isProcessing && (
                            <Button variant="ghost" size="icon" className="h-6 w-6" onClick={() => {
                              removeFile(i);
                              setSelectedFileIndexes(prev => {
                                const next = new Set<number>();
                                prev.forEach(idx => { if (idx < i) next.add(idx); else if (idx > i) next.add(idx - 1); });
                                return next;
                              });
                            }}>
                              <X className="h-3.5 w-3.5" />
                            </Button>
                          )}
                        </div>
                      );
                    })}
                  </div>
                )}


                {/* Manual rank button when auto-rank is OFF */}
                {profile?.auto_rank_enabled === false && files.length > 0 && !ranking && (
                  <Button
                    className="w-full gap-1.5"
                    onClick={handleRankClick}
                    disabled={!jobDescription.trim() || (selectedFileIndexes.size === 0 && files.length > 0)}
                  >
                    <Zap className="h-4 w-4" />
                    {selectedFileIndexes.size > 0
                      ? `Rank ${selectedFileIndexes.size} of ${files.length} Resume${selectedFileIndexes.size !== 1 ? "s" : ""}`
                      : `Select resumes to rank`}
                  </Button>
                )}
              </CardContent>
            </Card>

            {/* Resume Inbox Email card — only shown for existing jobs with a job inbox */}
            {isExistingJob && selectedJob?.inbox_email && (
              <Card className="border-border">
                <CardContent className="pt-5 pb-5 space-y-4">
                  <div className="flex items-start gap-3">
                    <div className="w-9 h-9 rounded-lg bg-muted flex items-center justify-center shrink-0 mt-0.5">
                      <Mail className="h-[18px] w-[18px] text-primary" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2 flex-wrap">
                        <p className="text-sm font-semibold text-foreground">Resume Inbox</p>
                        <Badge variant="outline" className="text-[11px] px-1.5 py-0 border-primary/30 text-primary bg-primary/5">Auto-collect</Badge>
                      </div>
                      <p className="text-xs text-muted-foreground mt-0.5 leading-relaxed">
